    private void startTls()throws Exception{
        byte[] keyBytes,certificateBytes;try(InputStream in=getContext().getAssets().open("browser-fixture-key.pem");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);keyBytes=android.util.Base64.decode(out.toString("UTF-8").replaceAll("-----[^-]+-----", "").replaceAll("\\s", ""),android.util.Base64.DEFAULT);}try(InputStream in=getContext().getAssets().open("browser-fixture-cert.pem");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);certificateBytes=out.toByteArray();}
        java.security.PrivateKey key=java.security.KeyFactory.getInstance("RSA").generatePrivate(new java.security.spec.PKCS8EncodedKeySpec(keyBytes));java.security.cert.Certificate certificate=java.security.cert.CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(certificateBytes));java.security.KeyStore keys=java.security.KeyStore.getInstance("PKCS12");keys.load(null,null);keys.setKeyEntry("fixture",key,"test-fixture".toCharArray(),new java.security.cert.Certificate[]{certificate});javax.net.ssl.KeyManagerFactory managers=javax.net.ssl.KeyManagerFactory.getInstance(javax.net.ssl.KeyManagerFactory.getDefaultAlgorithm());managers.init(keys,"test-fixture".toCharArray());javax.net.ssl.SSLContext ssl=javax.net.ssl.SSLContext.getInstance("TLS");ssl.init(managers.getKeyManagers(),null,new java.security.SecureRandom());tlsServer=ssl.getServerSocketFactory().createServerSocket(0,16,InetAddress.getByName("127.0.0.1"));tlsBase="https://127.0.0.1:"+tlsServer.getLocalPort();Thread fixture=new Thread(()->{while(running)try(Socket socket=tlsServer.accept()){socket.setSoTimeout(4000);byte[] body="<title>TLS reached</title>Untrusted test fixture".getBytes(StandardCharsets.UTF_8);OutputStream out=socket.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.write(body);out.flush();}catch(IOException ignored){}},"browser-test-tls");fixture.setDaemon(true);fixture.start();
    }
    private void tapWeb(String selector)throws Exception{await(()->"\"complete\"".equals(js("document.readyState")),"Web page ready for touch");Thread.sleep(250);String script="(()=>{let r=document.querySelector("+org.json.JSONObject.quote(selector)+").getBoundingClientRect();return [r.left+r.width/2,r.top+r.height/2,window.innerWidth]})()";org.json.JSONArray xy=new org.json.JSONArray(js(script));float[] point=new float[2];runOnMainSync(()->{int[] location=new int[2];browser.web().getLocationOnScreen(location);float scale=browser.web().getWidth()/(float)xy.optDouble(2);point[0]=location[0]+(float)xy.optDouble(0)*scale;point[1]=location[1]+(float)xy.optDouble(1)*scale;});check(activity.hasWindowFocus(),"Launcher owns focus for web touch");progress("web touch "+selector+" at "+point[0]+","+point[1]);tap(point[0],point[1]);}
    private void tap(float x,float y)throws Exception{long time=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(time,time,MotionEvent.ACTION_DOWN,x,y,0);down.setSource(InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(down,true);down.recycle();Thread.sleep(70);MotionEvent up=MotionEvent.obtain(time,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,x,y,0);up.setSource(InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(up,true);up.recycle();Thread.sleep(150);}
